  columns_css.gsub!("      .card__comments,\n", "      .card__boosts,\n      .card__comments,\n")
  columns_css.gsub!("          .card__comments,\n", "          .card__boosts,\n          .card__comments,\n")
  File.write("app/assets/stylesheets/card-columns.css", columns_css)

  trays_css = File.read("app/assets/stylesheets/trays.css")
  trays_css.sub!("    .card__comments,\n", "    .card__boosts,\n    .card__comments,\n")
  File.write("app/assets/stylesheets/trays.css", trays_css)
'
